SELECT
FROM ai_provider WHERE del_flag = '0'
AND provider_name LIKE CONCAT('%', #{providerName}, '%')
AND provider_type IN ('alibaba', 'dashscope') AND provider_type IN ('moonshot', 'kimi') AND provider_type IN ('volcengine', 'volcanic_engine') AND provider_type IN ('siliconflow', 'silicon_flow') AND provider_type IN ('baidu', 'wenxin') AND provider_type IN ('tencent', 'hunyuan') AND provider_type IN ('xunfei', 'spark') AND provider_type IN ('google', 'gemini') AND provider_type IN ('anthropic', 'claude') AND provider_type IN ('localai', 'local_ai') AND provider_type = #{providerType}
AND status = #{status}
ORDER BY create_time DESC
